ee:message.ee:set-payload:
%dw 2.0
output application/json

var raw = vars.getBalanceResponse default {}
var balance = raw["content"] default []
var packsDetails = vars.responsesPacks default []

fun mapItem(d) = {
    name: d.name,
    trafficLimitValueOrig: d.trafficLimitValueOrig default 0,
    trafficLimitValue: d.trafficLimitValue default 0,
    trafficLimitValueRenewal: d.trafficLimitValueRenewal default 0,
    category: d.category,
    "type": d["type"],
    trafficLimitValueOnRenewal: d.trafficLimitValueOnRenewal default 0
}

var nonPacks =
    (balance filter ((item) -> item["type"] != "PACK"))
        map ((item) -> mapItem(item))

var packItems =
    (balance filter ((item) -> item["type"] == "PACK"))

var expandedPacks =
    flatten(
        (packItems map ((pack) ->
            flatten(
                ((pack["childs"] default []) map ((child) ->
                    (packsDetails
                        filter ((p) -> p["id"] == child["id"]))
                        map ((d) -> mapItem(d))
                ))
            )
        ))
    )

---
{
    ExternalId: vars.connectionNumber,
    description: "Consulta Exitosa",
    Content: nonPacks ++ expandedPacks
}


%dw 2.0
output application/json
---
{
    status: 500,
    code: "GET_BALANCE_STRUCTURED",
    message: {
        message: vars.errorMessageOutput
    },
    messageServer: "Error obtaining subscription balance",
    cause: [
        {
            origin: app.name,
            message: "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
        }
    ]
}
